export type RateCircuitBreakerState = "closed" | "open" | "half-open";

export interface RateCircuitBreakerOptions {
  /** Number of failures in the sliding window required to open the circuit. */
  threshold: number;
  /** Length of the failure window in milliseconds. */
  windowMs: number;
  /** Length of the open state before a probe is admitted. */
  cooldownMs: number;
  /** Injectable monotonic clock. Defaults to Date.now. */
  clock?: () => number;
}

export interface RateCircuitBreakerSnapshot {
  state: RateCircuitBreakerState;
  failureCount: number;
  openedAt: number | null;
  probeInFlight: boolean;
}

/**
 * A small, deterministic circuit breaker for exceptional call rates.
 *
 * The breaker is deliberately only an admission/rate boundary. It does not
 * perform requests and must not be used as a replacement for SSRF checks,
 * loop guards, approvals, or budget/loop protection.
 */
export class RateCircuitBreaker {
  private currentState: RateCircuitBreakerState = "closed";
  private readonly failureTimestamps: number[] = [];
  private openedAt: number | null = null;
  private probeInFlight = false;
  private lastClock = Number.NEGATIVE_INFINITY;
  private readonly clock: () => number;

  public constructor(private readonly options: RateCircuitBreakerOptions) {
    if (!Number.isFinite(options.threshold) || options.threshold < 1) {
      throw new Error("rate circuit breaker threshold must be at least 1");
    }
    if (!Number.isFinite(options.windowMs) || options.windowMs < 0) {
      throw new Error("rate circuit breaker windowMs must be non-negative");
    }
    if (!Number.isFinite(options.cooldownMs) || options.cooldownMs < 0) {
      throw new Error("rate circuit breaker cooldownMs must be non-negative");
    }
    this.clock = options.clock ?? (() => Date.now());
  }

  public get state(): RateCircuitBreakerState {
    this.advanceToHalfOpenIfReady();
    return this.currentState;
  }

  /**
   * Returns true when a request may proceed. An open circuit rejects all
   * requests during cooldown. When cooldown expires exactly one half-open
   * probe is admitted.
   */
  public canRequest(): boolean {
    this.advanceToHalfOpenIfReady();
    if (this.currentState === "open") {
      return false;
    }
    if (this.currentState === "half-open") {
      if (this.probeInFlight) {
        return false;
      }
      this.probeInFlight = true;
      return true;
    }
    return true;
  }

  public allowRequest(): boolean {
    return this.canRequest();
  }

  public beforeRequest(): boolean {
    return this.canRequest();
  }

  /** Records a successful call. Success only closes a half-open probe. */
  public recordSuccess(): RateCircuitBreakerState {
    this.advanceToHalfOpenIfReady();
    if (this.currentState === "half-open" && this.probeInFlight) {
      this.currentState = "closed";
      this.openedAt = null;
      this.probeInFlight = false;
      this.failureTimestamps.length = 0;
    }
    return this.currentState;
  }

  /** Records a failed call and opens the circuit when the threshold is met. */
  public recordFailure(): RateCircuitBreakerState {
    const now = this.readClock();
    this.advanceToHalfOpenIfReady(now);
    if (this.currentState === "half-open") {
      this.open(now);
      return this.currentState;
    }
    if (this.currentState === "open") {
      return this.currentState;
    }
    this.pruneFailures(now);
    this.failureTimestamps.push(now);
    if (this.failureTimestamps.length >= this.options.threshold) {
      this.open(now);
    }
    return this.currentState;
  }

  public reset(): void {
    this.currentState = "closed";
    this.failureTimestamps.length = 0;
    this.openedAt = null;
    this.probeInFlight = false;
  }

  public snapshot(): RateCircuitBreakerSnapshot {
    this.advanceToHalfOpenIfReady();
    return {
      state: this.currentState,
      failureCount: this.failureTimestamps.length,
      openedAt: this.openedAt,
      probeInFlight: this.probeInFlight,
    };
  }

  private open(now: number): void {
    this.currentState = "open";
    this.openedAt = now;
    this.probeInFlight = false;
  }

  private advanceToHalfOpenIfReady(now = this.readClock()): void {
    if (this.currentState !== "open" || this.openedAt === null) {
      return;
    }
    if (now - this.openedAt < this.options.cooldownMs) {
      return;
    }
    this.currentState = "half-open";
    this.probeInFlight = false;
  }

  private pruneFailures(now: number): void {
    const cutoff = now - this.options.windowMs;
    while (this.failureTimestamps.length > 0 && this.failureTimestamps[0] < cutoff) {
      this.failureTimestamps.shift();
    }
  }

  private readClock(): number {
    const value = this.clock();
    if (!Number.isFinite(value)) {
      throw new Error("rate circuit breaker clock must return a finite number");
    }
    if (value < this.lastClock) {
      return this.lastClock;
    }
    this.lastClock = value;
    return value;
  }
}

export function createRateCircuitBreaker(options: RateCircuitBreakerOptions): RateCircuitBreaker {
  return new RateCircuitBreaker(options);
}

